    n1, n2, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            edges.append((u, v, i))

    # Build adjacency and compute degrees
    degree_u = defaultdict(int)
    degree_v = defaultdict(int)

    for u, v, idx in edges:
        degree_u[u] += 1
        degree_v[v] += 1

    # minDegree is minimum across all vertices
    min_deg = min(degree_u[k] for k in degree_u)
    if degree_v:
        min_deg = min(min_deg, min(degree_v[k] for k in degree_v))

    # For each k from 1 to minDegree
    output_lines = []

    for k in range(1, min_deg + 1):
        # Greedy approach: keep edges until all vertices have degree >= k
        # Use edges with lowest indices preferred

        selected_edges = set()
        current_u = defaultdict(int)
        current_v = defaultdict(int)

        for u, v, idx in edges:
            new_edge = (u, v, idx)
            selected_edges.add(new_edge)
            current_u[u] += 1
            current_v[v] += 1

            # Check if all vertices now have degree >= k
            temp_valid = True
            for node in set(current_u.keys()) | set(current_v.keys()):
                degree = current_u.get(node, 0) + current_v.get(node, 0)
                if node in degree_u:
                    if degree < k:
                        temp_valid = False
                        break
                elif node in degree_v:
                    if degree < k:
                        temp_valid = False
                        break

            # This approach doesn't work - need better logic

        # Better: select edges greedily by checking which edges reduce the "deficit"
        best_selection = None
        best_size = float('inf')

        for attempt in range(100):
            current_sel = set()
            for u, v, idx in edges:
                current_sel.add(idx)

            # Check validity - both U and V vertices must have >= k edges
            valid = True

            for node in range(1, n1 + 1):
                cnt = sum(1 for e_idx in current_sel if edges[e_idx-1][0] == node)
                if cnt < k:
                    valid = False
                    break

            if not valid:
                for node in range(1, n2 + 1):
                    cnt = sum(1 for e_idx in current_sel if edges[e_idx-1][1] == node)
                    if cnt < k:
                        valid = False
                        break

            if valid:
                if len(current_sel) < best_size:
                    best_size = len(current_sel)
                    best_selection = current_sel

        if best_selection is not None:
            result = sorted(list(best_selection))
            output_lines.append(str(len(result)) + (" " + " ".join(map(str, result)) if result else ""))
        else:
            output_lines.append("0")

    return '\n'.join(output_lines)

