def solve_probability(n, m, k):
    import math

    if m == 0:
        # No one with 20 euros, always succeed
        return "1\n"

    if k >= m:
        # We have enough initial notes to give change to everyone with 20
        return "1\n"

    if n < m - k:
        # Impossible to satisfy the condition
        return "0\n"

    # Total number of arrangements: C(n+m, n)
    total = math.comb(n + m, n)

    # Invalid arrangements using inclusion-exclusion
    invalid = 0
    for i in range(1, m - k + 1):
        invalid += math.comb(n + m, m - i)

    valid = total - invalid

    probability = valid / total

    return f"{probability:.12f}\n"

# However, for robustness testing, let's also implement the proper solution
def proper_solution(n, m, k):
    """
    Calculate the probability that Charlie can always give change.

    This is solved using the reflection principle for counting paths
    that never go below a certain boundary.
    """

    if m == 0 or k >= m or n >= m:
        # If no 20-euro notes, or we have enough initial 10s, or enough 10s
        return "1\n"

    if n < m - k:
        # Not enough 10-euro notes even if all 20s come after all 10s
        return "0\n"

    # We need to count paths from (0, 0) to (n, m) that never have j - i > k
    # where i = # of 10-euro people, j = # of 20-euro people

    # Using the ballot theorem for the case with initial advantage k
    # The formula for valid paths is:
    # sum from i=0 to m-k-1 of (-1)^i * C(n+m, m-i)

    valid_paths = 0
    for i in range(m - k + 1):
        if i % 2 == 0:
            valid_paths += math.comb(n + m, m - i)
        else:
            valid_paths -= math.comb(n + m, m - i)

    total_paths = math.comb(n + m, n)

    probability = valid_paths / total_paths
    return f"{probability:.12f}\n"

def solution(input_str):
