    t = int(lines[0])
    idx = 1
    results = []

    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        # Find length of longest non-decreasing subsequence
        # Using patience sorting with binary search
        dp = []
        for x in a:
            # Binary search for first element >= x
            lo, hi = 0, len(dp)
            while lo < hi:
                mid = (lo + hi) // 2
                if dp[mid] < x:
                    lo = mid + 1
                else:
                    hi = mid

            if lo == len(dp):
                dp.append(x)
            else:
                # Replace existing value to maintain non-decreasing property
                dp[lo] = x

        max_len = len(dp)
        results.append(str(n - max_len))

    return '\n'.join(results)

