def get_prime_factors(n):
    """Get all prime factors of n (not with multiplicity)"""
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def get_divisors(n):
    """Generate all divisors of n using prime factorization"""
    if n == 1:
        return []

    factors = get_prime_factors(n)
    if not factors:
        return []

    # Build divisor list from prime factorization
    unique_primes = {}
    for p in factors:
        unique_primes[p] = unique_primes.get(p, 0) + 1

    result = [1]
    for p, count in unique_primes.items():
        temp = result[:]
        for i in range(count):
            p_power = p ** (i + 1)
            for d in temp:
                result.append(d * p_power)

    result.sort()
    return [d for d in result if d > 1]

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_hamiltonian_cycle_with_communities(n, divs):
    """
    Try to find a valid ordering where adjacent divisors share a prime factor.
    Uses greedy approach with backtracking.
    """
    m = len(divs)
    if m <= 1:
        return divs

    # Build adjacency based on shared prime factors
    adj = [[] for _ in range(m)]
    prime_to_divs = defaultdict(list)

    for i, d in enumerate(divs):
        factors = get_prime_factors(d)
        for p in factors:
            prime_to_divs[p].append(i)

    for i in range(m):
        for j in range(i + 1, m):
            if gcd(divs[i], divs[j]) > 1:
                adj[i].append(j)
                adj[j].append(i)

    # Try DFS with pruning
    path = []
    visited = [False] * m

    def find_path(start):
        if len(path) == m - 1:
            # Check if we can connect back to start
            for v in adj[start]:
                if visited[v]:
                    return path
            return None

        # Greedy choice: try neighbors
        for v in adj[path[-1]]:
            if not visited[v]:
                visited[v] = True
                path.append(v)
                result = find_path(start)
                if result is not None:
                    return result
                path.pop()
                visited[v] = False

        return path

    for start in range(m):
        path = [start]
        visited = [False] * m
        visited[start] = True
        for v in adj[start]:
            if not visited[v]:
                result = find_path(start)
                if result is not None:
                    return path

        if find_path(start):
            return path

    return None

