def find_sccs(n, edges):
    """Find all SCCs using Tarjan's algorithm"""
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)

    index = 0
    on_stack = [False] * (n + 1)
    stack = []
    indices = [-1] * (n + 1)
    low = [-1] * (n + 1)
    scc_count = 0
    scc_vertices = []
    visited_nodes = [False] * (n + 1)

    def dfs(v):
        nonlocal index
        index += 1
        indices[v] = index
        low[v] = index
        stack.append(v)
        on_stack[v] = True

        for u in adj[v]:
            if indices[u] == -1:
                dfs(u)
                low[v] = min(low[v], low[u])
            elif on_stack[u]:
                low[v] = min(low[v], indices[u])

        if low[v] == indices[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            scc_vertices.append(scc)

    for v in range(1, n + 1):
        if indices[v] == -1:
            dfs(v)

    return scc_vertices

def has_cycle_in_scc(scc, edges, n):
    """Check if the subgraph induced by scc has a cycle"""
    scc_set = set(scc)
    adj = {v: [] for v in scc}
    for u, v in edges:
        if u in scc_set and v in scc_set:
            adj[u].append(v)

    def has_path(start, target, visited):
        stack = [(start, iter(adj[start]))]
        while stack:
            node, neighbors = stack[-1]
            if node == target:
                return True
            try:
                nxt = next(neighbors)
                if nxt not in visited:
                    visited.add(nxt)
                    stack.append((nxt, iter(adj[nxt])))
            except StopIteration:
                stack.pop()
        return False

    for v in scc:
        visited = {v}
        # Check if any node can reach itself (cycle)
        for u, neighbors in adj.items():
            if u == v:
                continue
            if v in adj[u] and has_path(u, v, visited):
                return True
            if has_path(u, u, visited) and visited:
                return True

    return False

