def solution(input_str):
    """
    Find when the last hole disappears in the growing circles problem.
    Answer is the maximum circumradius of all valid triangles, or -1 if no valid triangles exist.
    """
    if not input_str.strip():
        return "-1"

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            points.append((int(parts[0]), int(parts[1])))

    if n < 3:
        return "-1"

    # Check if all points are collinear
    def is_collinear(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) == (p2[1] - p1[1]) * (p3[0] - p1[0])

    all_collinear = True
    found_triangle = False
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if not is_collinear(points[i], points[j], points[k]):
                    all_collinear = False
                    found_triangle = True
                    break
            if not all_collinear:
                break
        if not all_collinear:
            break

    if all_collinear or not found_triangle:
        return "-1"

    # Find maximum circumradius
    max_r = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                p1, p2, p3 = points[i], points[j], points[k]
                if is_collinear(p1, p2, p3):
                    continue

                # Side lengths
                a = ((p2[0] - p1[0])**2 + **(p2[1] - p1[1])2)**0.5
                b = ((p3[0] - p1[0])**2 + **(p3[1] - p1[1])2)**0.5
                c = ((p3[0] - p2[0])**2 + **(p3[1] - p2[1])2)**0.5

                # Area using cross product (2*area)
                area2 = abs(p1[0] * (p2[1] - p3[1]) + 
                            p2[0] * (p3[1] - p1[1]) + 
                            p3[0] * (p1[1] - p2[1]))

                if area2 == 0:
                    continue

                # Circumradius R = abc / (4 * area)
                r = (a * b * c) / (4.0 * area2)
                max_r = max(max_r, r)

    return "{:.8f}".format(max_r)

