    if k == 0:
        if 'N' in s:
            return "NO\n"
        # Check if we can set all ? to Y
        return "YES\n"

    # Find all ? positions
    question_positions = [i for i, c in enumerate(s) if c == '?']
    num_questions = len(question_positions)

    # Enumerate all possible assignments (2^num_questions)
    # For n <= 100 and sparse ?, this is manageable
    import itertools
    subscription = itertools.product(['N', 'Y'], repeat=num_questions)

    for assignment in subscription:
        temp = list(s)
        for i, c in zip(range(num_questions), assignment):
            temp[question_positions[i]] = c
        temp_str = ''.join(temp)

        # Calculate max consecutive N
        max_consecutive = 0
        current = 0
        for c in temp_str:
            if c == 'N':
                current += 1
                max_consecutive = max(max_consecutive, current)
            else:
                current = 0

        if max_consecutive == k:
            return "YES\n"

    return "NO\n"

