        d.append(int(parts[1]))
        if i > 0:
            parent = int(parts[2]) - 1  # 0-indexed
            children[parent].append(i)

    INF = float('inf')

    # dp_a[u] will store [cost to buy k items in subtree u without coupon u]
    # dp_b[u] will store [cost to buy k items in subtree u with coupon u]
    # Use dictionary for sparse representation

    def merge_dicts(base_dict, add_dict):
        """Add two dicts as knapsack-style items"""
        result = {}
        for i in range(len(base_dict)):
            cost = base_dict.get(i, INF)
            if cost == INF:
                continue
            for j in range(len(add_dict)):
                cost2 = add_dict.get(j, INF)
                if cost2 == INF:
                    continue
                    res[i+j] = min(res[i+j], cost + cost2)
        return res

    # Build tree from children (adjacency list)
    # Since i > 1 always has parent < i, we can process in reverse order

    # node[i] = [a_dict, b_dict]
    dp = {}

    for i in range(n - 1, -1, -1):
        if i not in dp:
            dp[i] = ([], ())

        # Base case
        if i in dp:
            dp[i] = ({0: 0}, {0: INF})

        # Merge children
        # Start with just buying 0 items from this node's perspective
        a_dict = {0: 0}
        b_dict = {0: INF}

        for child in children[i]:
            child_a, child_b = dp.get(child, ({}, {}))

            # For a state: children can only use their own a (no coupons)
            merged_a = {}
            for k1, c1 in a_dict.items():
                if c1 == INF:
                    continue
                for k2, c2 in child_a.items():
                    if c2 == INF:
                        continue
                    new_key = k1 + k2
                    if new_key not in merged_a or merged_a[new_key] > c1 + c2:
                        merged_a[new_key] = c1 + c2

            # For b state: children can use either a or b (since parent coupon is used)
            # But wait - b already assumed parent uses its coupon, which enables child
            merged_b = {}
            for k1, c1 in b_dict.items():
                if c1 == INF:
                    continue
                for k2, c2a in child_a.items():
                    if c2a == INF:
                        continue
                    for k2, c2b in child_b.items():
                        if c2b == INF:
                            continue
                        min_cost = min(c2a, c2b)
                        new_key = k1 + k2
                        if new_key not in merged_b or merged_b[new_key] > c1 + min_cost:
                            merged_b[new_key] = c1 + min_cost

            a_dict = merged_a
            b_dict = merged_b

        # Update dp[i]
        dp[i] = (a_dict, b_dict)

        # After child merge, now handle item i itself
        # a[i]: can either not buy i or buy without coupon
        # b[i]: must have parent coupon, so buy i with coupon

        if i != 0:
            # Node 0 (root) has no parent, so b[i] is valid only if we're at root
            # For non-root, b is valid only if parent uses coupon
            dp[i] = (a_dict, b_dict)

        # Now handle item i itself
        # a[i]: min of (not buying u, buying u without coupon)
        # b[i]: buy u with coupon
        pass

