def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Check for odd n - impossible to pair everyone up
    if n % 2 != 0:
        return "-1\n"

    # Parse cost matrix
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        vals = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j != i:
                costs[i][j] = vals[idx]
                idx += 1

    # Build preference lists (each city ranked by connection cost to others)
    prefs = []
    for i in range(n):
        # Sort all other cities by cost from this city's perspective
        city_prefs = sorted([j for j in range(n) if j != i], key=lambda x: costs[i][x])
        prefs.append(city_prefs)

    # Initial matching: arbitrary pairing
    match = {}
    for i in range(0, n, 2):
        match[i] = i + 1
        match[i + 1] = i

    # Check for blocking pairs and resolve them
    changed = True
    while changed:
        changed = False

        # Get current partners
        partners = {}
        for person in range(n):
            partners[person] = match.get(person, -1)

        # Look for blocking pairs
        for u in range(n):
            if match.get(u) == -1:
                continue

            # Find v that u prefers over current partner and 
            # v prefers u over their current partner
            for v in prefs[u]:
                if v <= u or u <= v:
                    if u == v:
                        continue
                    # Check if they're already matched together
                    if (match.get(v) == u and match.get(u) == v):
                        continue

                    w = partners.get(u)  # u's current partner
                    z = partners.get(v)  # v's current partner

                    if w == v:
                        continue
                    if z == u:
                        continue

                    # u prefers v over w
                    u_prefers_v = False
                    if w != -1:
                        if v in prefs[u] and w in prefs[u]:
                            idx_v = prefs[u].index(v)
                            idx_w = prefs[u].index(w)
                            u_prefers_v = idx_v < idx_w
                    else:
                        u_prefers_v = True

                    if not u_prefers_v:
                        continue

                    # v prefers u over z
                    v_prefers_u = False
                    if z != -1:
                        if u in prefs[v] and z in prefs[v]:
                            idx_u = prefs[v].index(u)
                            idx_z = prefs[v].index(z)
                            v_prefers_u = idx_u < idx_z
                    else:
                        v_prefers_u = True

                    if v_prefers_u:
                        # Blocking pair found - make them match
                        match[u] = v
                        match[v] = u
                        if w != -1 and w != v:
                            del match[w]
                        if z != -1 and z != u:
                            del match[z]
                        changed = True
                        break

            if changed:
                break

    # Convert to 1-indexed output
    result = []
    for i in range(n):
        partner = match.get(i, -1)
        result.append(str(partner + 1))

    return '\n'.join(result) + '\n'

# Solution code for the safe breaking problem
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        line = lines[i].split()
        attempts.append((line[0], int(line[1])))

    # Convert binary strings to integers
    attempts_bit = [int(s, 2) for s, _ in attempts]
    attempts_count = [c for _, c in attempts]

    def count_matches_first_half(val1, n1, n2):
        """For a first half value, return tuple of matches with each attempt's first half"""
        result = []
        mask = (1 << n1) - 1
        for i in range(m):
            # Extract first n1 bits from attempt and count matches
            result.append(bin(val1 & attempts_bit[i] & mask).count('1'))
        return tuple(result)

    def count_matches_second_half(val2, n1, n2):
        """For a second half value, return tuple of matches with each attempt's second half"""
        result = []
        mask = (1 << n2) - 1
        for i in range(m):
            # Extract last n2 bits from attempt and count matches
            result.append(bin((val2 | mask) & attempts_bit[i]).count('1'))
        return tuple(result)

    # Generate all possible first half values and cache their match counts
    # key -> tuple of match counts for each attempt, value -> count of such configs
    first_half_cache = {}
    for val1 in range(1 << (n >> 1)):
        key = count_matches_first_half(val1, (n >> 1), n - (n >> 1))
        first_half_cache[key] = first_half_cache.get(key, 0) + 1

    # Now iterate through second half and check compatibility
    ans = 0
    half1_len = n >> 1
    half2_len = n - half1_len
    mask2 = (1 << half2_len) - 1

    for val2 in range(1 << half2_len):
        key2 = count_matches_second_half(val2, half1_len, half2_len)
        for key1, count1 in first_half_cache.items():
            if all(key1[i] + key2[i] == attempts_count[i] for i in range(m)):
                ans += count1

    return str(ans)

